INSERT IGNORE INTO `announcements` (`id`, `author_user_id`, `title`, `body`, `audience`, `section_id`, `expires_on`, `created_at_utc`, `updated_at_utc`, `assignment_id`, `category`, `starts_on`) VALUES
(1, 4, 'Welcome to the new school year', 'Classes are on. Please check your courses, open your handouts and read the syllabus of each one. If something is missing, write to your teacher.', 'Everyone', NULL, NULL, (TIMESTAMP(UTC_DATE()) + INTERVAL -3020400 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -3020400 SECOND), NULL, 'Other', NULL),
(2, 4, 'Faculty meeting on Friday, 3:00 PM', 'We will talk about the grades of the first term and the teacher evaluation. Please bring the grades of your courses.', 'Teachers', NULL, (UTC_DATE() + INTERVAL 4 DAY), (TIMESTAMP(UTC_DATE()) + INTERVAL -75600 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -75600 SECOND), NULL, 'TeachersMeeting', NULL),
(3, 4, 'No classes on Monday', 'Monday is a holiday. Classes continue on Tuesday. Enjoy the long weekend and finish your activities before you rest.', 'Everyone', NULL, (UTC_DATE() + INTERVAL 6 DAY), (TIMESTAMP(UTC_DATE()) + INTERVAL -68400 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -68400 SECOND), NULL, 'Holiday', NULL),
(4, 4, 'Semester break', 'The semester break starts after the last exam of the 1st term. The 2nd term starts on Monday, November 2.', 'Everyone', NULL, (UTC_DATE() + INTERVAL 20 DAY), (TIMESTAMP(UTC_DATE()) + INTERVAL -252000 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -252000 SECOND), NULL, 'SemesterBreak', (UTC_DATE() + INTERVAL 14 DAY)),
(5, 7, 'Bring your calculators', 'For the activity next week please bring a calculator. We will practice the journal and the ledger.', 'Students', (SELECT `id` FROM `sections` WHERE `school_year_id` = 1 AND `strand_id` = 1 AND `grade_level` = 11 AND `name` = 'A'), (UTC_DATE() + INTERVAL 7 DAY), (TIMESTAMP(UTC_DATE()) + INTERVAL -72000 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -72000 SECOND), 1, 'Other', NULL),
(6, 7, 'Quiz 1 is on Wednesday', 'Quiz 1 of Business Accounting covers Handouts 1 and 2. It has 3 questions and 15 minutes.', 'Students', (SELECT `id` FROM `sections` WHERE `school_year_id` = 1 AND `strand_id` = 1 AND `grade_level` = 11 AND `name` = 'A'), (UTC_DATE() + INTERVAL 3 DAY), (TIMESTAMP(UTC_DATE()) + INTERVAL -64800 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -64800 SECOND), 1, 'Exam', NULL);
