(1, 1, 'Syllabus: Business Accounting', NULL, NULL, NULL, 0, NULL, NULL, (TIMESTAMP(UTC_DATE()) + INTERVAL -154800 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -154800 SECOND), 1, 0),
(2, 1, 'Handout 1: Introduction to Business Accounting', 'What this course is about and how we work.', 'Welcome to Business Accounting. In this first lesson we look at the main ideas of the course, how the grades are computed and how to study for it. Read the notes, then do the activity.', 'https://example.com/lessons/business_accounting-1', 1, (TIMESTAMP(UTC_DATE()) + INTERVAL -1897200 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -1897200 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -2149200 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -2149200 SECOND), 0, 0),
(3, 1, 'Handout 2: Key ideas of Business Accounting', 'The main concepts, with examples.', 'This lesson explains the key ideas of Business Accounting with worked examples. Take the quiz when you finish reading, and send the worksheet before it is due.', NULL, 2, (TIMESTAMP(UTC_DATE()) + INTERVAL -1292400 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -1292400 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -1544400 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -1544400 SECOND), 0, 0),
(4, 1, 'Handout 3: Business Accounting in practice', 'Using what you learned in a small project.', 'In this lesson you apply what you learned in Business Accounting. The task performance asks you to make a short output and explain it.', NULL, 3, (TIMESTAMP(UTC_DATE()) + INTERVAL -687600 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -687600 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -939600 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -939600 SECOND), 0, 0),
(5, 1, 'Handout 4: Review of Business Accounting', 'A review before the term exam. (Scheduled.)', 'Review of the topics of Business Accounting. This handout appears on its date.', NULL, 4, (TIMESTAMP(UTC_DATE()) + INTERVAL 432000 SECOND), NULL, (TIMESTAMP(UTC_DATE()) + INTERVAL -507600 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -507600 SECOND), 0, 0),
