INSERT IGNORE INTO `messages` (`id`, `sender_user_id`, `recipient_user_id`, `body`, `read_at_utc`, `created_at_utc`, `updated_at_utc`) VALUES
(1, 19, 7, 'Good morning sir. When is Activity 2 due?', (TIMESTAMP(UTC_DATE()) + INTERVAL -162000 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -169200 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -169200 SECOND)),
(2, 7, 19, 'Good morning Juan. It is due this week. You can see the exact date in your calendar.', (TIMESTAMP(UTC_DATE()) + INTERVAL -158400 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -162000 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -162000 SECOND)),
(3, 19, 7, 'Thank you sir!', (TIMESTAMP(UTC_DATE()) + INTERVAL -154800 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -158400 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -158400 SECOND)),
(4, 20, 7, 'Sir, may I send my worksheet tomorrow? I was not feeling well.', NULL, (UTC_TIMESTAMP(6) + INTERVAL -21876.665175 SECOND), (UTC_TIMESTAMP(6) + INTERVAL -21876.665175 SECOND)),
